#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-no-padding-folders.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-no-padding-folders — refuses README-only "padding" sub-folders
 * inside src/features/<name>/.
 *
 * A sub-folder under src/features/<name>/ that contains zero .ts/.tsx
 * files is empty padding (typically a README.md that exists ONLY to
 * satisfy a "must have all N sub-folders" rule). This gate refuses it.
 *
 * The doctrine: a feature has only the sub-folders it actually uses.
 * No folder exists just to claim shape.
 *
 * Exception: `__specs__/` is allowed to have 0 .ts files because it
 * holds YAML.
 *
 * Usage:
 *   node scripts/verify/verify-no-padding-folders.mjs [<source-root>]
 *
 * Exits 0 when every sub-folder has real code; non-zero otherwise.
 */
import { readdir } from "node:fs/promises";
import { join, relative } from "node:path";
import { existsSync } from "node:fs";

const SOURCE_ROOT = process.argv[2] || "src";
const REPO_ROOT = process.cwd();
const featuresDir = join(REPO_ROOT, SOURCE_ROOT, "features");

const IGNORE_DIRS = new Set([
  "node_modules",
  ".next",
  ".turbo",
  "coverage",
  "test-results",
  "playwright-report",
  ".git",
  "dist",
  "build",
  "out",
  "__specs__", // YAML-only by design
]);

if (!existsSync(featuresDir)) {
  process.stdout.write(
    `✅ verify-no-padding-folders — no src/features/ in this repo; nothing to check.\n`,
  );
  process.exit(0);
}

const violations = [];
let checked = 0;

const featureEntries = await readdir(featuresDir, { withFileTypes: true });
for (const feat of featureEntries) {
  if (!feat.isDirectory()) continue;
  if (IGNORE_DIRS.has(feat.name)) continue;
  // `features/shared/` holds cross-feature shared schemas / types
  // (SOURCE_FOLDERS.yaml.per_feature_structure); it is never a feature, so its
  // sub-folders are not subject to the padding check.
  if (feat.name === "shared") continue;
  const featDir = join(featuresDir, feat.name);
  await scanFeature(featDir, feat.name);
}

async function scanFeature(featDir, featName) {
  let subs;
  try {
    subs = await readdir(featDir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const sub of subs) {
    if (!sub.isDirectory()) continue;
    if (IGNORE_DIRS.has(sub.name)) continue;
    const subPath = join(featDir, sub.name);
    const tsCount = await countTsFiles(subPath);
    checked++;
    if (tsCount === 0) {
      violations.push(
        `${relative(REPO_ROOT, subPath)}: EMPTY PADDING — 0 .ts/.tsx files. Delete the folder or add real code.`,
      );
    }
  }
}

async function countTsFiles(dir) {
  let count = 0;
  await scan(dir);
  async function scan(d) {
    let entries;
    try {
      entries = await readdir(d, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      if (IGNORE_DIRS.has(e.name)) continue;
      const p = join(d, e.name);
      if (e.isDirectory()) {
        await scan(p);
      } else if (e.isFile()) {
        if (e.name.endsWith(".ts") || e.name.endsWith(".tsx")) count++;
      }
    }
  }
  return count;
}

if (violations.length === 0) {
  process.stdout.write(
    `✅ verify-no-padding-folders — ${checked} sub-folder(s) checked; every one has real code.\n`,
  );
  process.exit(0);
}

process.stderr.write(
  `\n❌ verify-no-padding-folders: ${violations.length} violation(s)\n`,
);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(
  `\n   ${checked} sub-folder(s) checked total.\n`,
);
process.exit(1);
